build("pregnancy-back-pain",dict(
desc="임신 중 허리가 끊어질 듯하거나 골반 뒤·치골이 아파 걷기 힘들다면 임신부 요통·골반띠 통증일 수 있습니다. 조기진통 신호와 주수에 맞춘 침·약침·추나·한약 관리를 인천 서구 365스마일한의원이 정리했습니다.",
answer="임신 중 허리·골반 통증은 배가 앞으로 나오며 허리가 젖혀지고, 출산을 준비하는 호르몬 영향으로 골반 인대가 느슨해지면서 생깁니다. 허리 가운데가 뻐근한 요통, 엉덩이 위 골반 뒤쪽이 찌르는 골반띠 통증, 두 다리 사이 앞쪽 뼈가 아픈 치골 결합 통증으로 나뉩니다. 다만 규칙적으로 배가 뭉치거나 출혈·물 같은 분비물이 비치면 통증 치료보다 산부인과 확인이 먼저입니다. 인천 서구 365스마일한의원은 주수와 상태를 확인한 뒤 금기 부위를 피해 침·약침·추나·한약으로 관리합니다.",
sections=[
("check","내 허리·골반 통증, 어떤 모습인가요?",CHECK(["오래 서 있거나 저녁이 되면 허리 가운데가 묵직하게 당긴다","엉덩이 위 보조개 자리 근처가 한쪽 또는 양쪽으로 콕콕 쑤신다","돌아눕거나 바지를 한 발로 서서 입을 때 골반이 시큰하다","두 다리 사이 앞쪽 뼈가 아파 걸음이 뒤뚱거린다","계단을 오르거나 차에서 내릴 때 골반이 어긋나는 느낌이 든다","허리 통증과 함께 배가 일정한 간격으로 단단해진다"],note="이 체크리스트는 진단 도구가 아닙니다. 마지막 항목처럼 통증이 배 뭉침과 같이 주기적으로 온다면 진통일 수 있으니 다니는 산부인과에 바로 연락하세요.")),
("red","통증 치료보다 산부인과·응급 진료가 먼저인 신호",UL(["허리나 아랫배 통증이 10분 안팎 간격으로 규칙적으로 오고 배가 뭉친다 (조기진통 의심)","질에서 피가 비치거나 물 같은 분비물이 흐른다 (양막 파수 의심)","열이 나고 소변 볼 때 아프거나, 한쪽 옆구리를 두드리면 울린다 (신우신염 의심)","태동이 평소보다 눈에 띄게 줄었다","다리에 힘이 빠지거나 대소변을 보기 어렵고, 엉덩이 주변 감각이 둔하다","한쪽 종아리가 붓고 아프거나 갑자기 숨이 찬다"])+"\n"+P("이런 신호가 있으면 <b>다니는 산부인과나 응급실</b>로 바로 가시고, 숨이 차거나 출혈이 많으면 119를 부르세요. 한의원 진료 중에 보여도 치료를 멈추고 산부인과로 안내합니다.")),
("why","임신하면 왜 허리와 골반이 아플까요?",P("임신부의 절반 가까이 또는 그 이상이 허리나 골반 통증을 겪는다는 보고가 있을 만큼 흔하지만, 참기만 할 일은 아닙니다.")+"\n"+UL([B("무게 중심 이동","배가 커질수록 몸이 앞으로 쏠리고, 이를 버티려 허리를 뒤로 젖히게 되어 허리 근육이 하루 종일 일합니다."),B("인대 이완","릴랙신 등 임신 호르몬이 골반 관절을 잇는 인대를 느슨하게 해, 걷거나 한 발로 설 때 관절이 흔들리며 아픕니다."),B("복근 약화와 잠","늘어난 배 근육이 몸통을 덜 받치고, 옆으로만 자다 보니 아침에 허리가 뻣뻣합니다.")])+"\n"+P("<b>골반띠 통증</b>은 허리보다 아래, 엉덩이 위 천장관절 부위나 치골 결합에 통증이 모이는 것을 말합니다. 허리를 굽힐 때보다 걷기, 돌아눕기, 한 발 서기에서 더 아픈 점이 일반 요통과 다릅니다.")),
("km","한의학은 임신 중 요통을 어떻게 보나요?",P("한의학에서는 임신 중 허리가 아픈 것을 <b>임신요통(姙娠腰痛)</b>, 또는 태(胎)를 품은 몸의 허리 병으로 다뤘습니다. 허리를 신(腎)의 집으로 보아, 태아를 기르느라 신의 정기가 쓰이면 허리 받침이 약해진다고 했습니다.")+"\n"+P("어머니의 혈(血)이 태아에게 모여 인대를 적실 혈이 모자라면 당기고 저린다고도 봅니다. 그래서 태를 편안히 하는 <b>안태(安胎)</b>를 먼저 두고, 그 안에서 막힌 흐름을 부드럽게 풉니다.")),
("types","나의 허리·골반 통증은 어떤 유형일까?",CARDS([
T("신허(腎虛)","허리가 시큰하고 힘없는 유형","임신 후기이거나 체력이 약한 분","오래 서 있으면 주저앉고 싶다","다리 힘 빠짐, 소변이 잦음, 쉽게 지침","맥이 가라앉고 약함, 압통은 적음","신을 보해 허리와 태를 함께 받치는 방향 (수태환 계열)","30분마다 자리에서 일어나 허리를 가볍게 펴 주세요."),
T("혈허(血虛)","당기고 저린 유형","입덧으로 못 먹었거나 빈혈이 있는 분","엉덩이가 당기고 밤에 다리에 쥐가 난다","어지러움, 얼굴이 창백함, 잠이 얕음","혀 색이 옅고 맥이 가늚","혈을 길러 근육과 인대를 적시는 방향 (당귀작약산 계열)","살코기와 푸른 채소를 끼니마다 곁들이세요."),
T("기체·경락 막힘","한 자리가 걸리는 유형","오래 앉아 일하거나 큰아이를 한쪽으로 안는 분","골반 뒤 한쪽이나 치골이 콕 찌른다","엉덩이 결림, 돌아누울 때 통증","천장관절·치골 부위 압통이 뚜렷함","막힌 경락을 풀어 골반 긴장을 줄이는 방향","돌아누울 때 두 무릎을 붙인 채 한 덩어리로 굴러 보세요.")],
intro="처방은 주수와 몸 상태를 보고 정하며, 처방명은 방향을 보여 주는 예시입니다.")),
("exam","한의원에서는 어떻게 진찰하나요?",UL([B("주수와 산전 검사","현재 주수, 산모 수첩의 검사 결과, 조산·출혈·전치태반 같은 주의 사항을 먼저 여쭙습니다."),B("통증 자리 나누기","허리 가운데인지, 엉덩이 위 골반 뒤인지, 치골인지 손으로 짚어 구분합니다."),B("부드러운 움직임 검사","누운 채 다리를 들어 보거나 골반을 가볍게 눌러 어느 관절에서 통증이 나는지 확인합니다. 배를 누르는 검사는 하지 않습니다."),B("복용 약","철분제·갑상선약 등 드시는 약을 알려 주시면 확인해 처방합니다.")])),
("treat","침·약침·추나·한약 치료는 어떻게 하나요?",H3("1. 침 치료")+"\n"+P("합곡(合谷)·삼음교(三陰交)·곤륜(昆侖)처럼 임신 중 피하라고 전해 온 혈과 아랫배, 천골 부위 혈은 쓰지 않고, 옆으로 누운 자세에서 아래 혈을 얕게 자극합니다.")+"\n"+UL([B("위중(委中)","무릎 뒤 오금 주름의 한가운데입니다. 허리 통증에 멀리서 함께 씁니다."),B("환도(環跳) 주변","엉덩이 옆 근육이 두툼한 자리로, 엉덩이 긴장을 풀 때 씁니다."),B("후계(後溪)","주먹을 쥐었을 때 새끼손가락 쪽 손바닥 가로 주름 끝입니다. 허리를 돌리기 힘들 때 씁니다.")])+"\n"+H3("2. 약침·초음파 가이드 약침")+"\n"+P("약침은 일반 약침과 초음파 가이드 약침을 모두 시행하며, 아픈 부위의 깊이와 주변 구조에 따라 진찰 후 골라 씁니다. 초음파 가이드 약침은 초음파 화면으로 바늘 끝을 확인하면서 놓는 방식입니다. 초음파로 천장관절 주변 인대와 엉덩이 근육의 두께, 붓기를 보면서 통증이 모인 인대 부위에만 바늘 끝이 닿게 합니다. 임신 중에는 주수와 상태를 확인한 뒤 놓을 자리, 깊이, 약액을 고르며, 아랫배와 허리의 금기 혈, 합곡·삼음교 같은 피해야 할 부위는 제외합니다.")+"\n"+H3("3. 추나·온열 요법")+"\n"+P("골반이 틀어져 걸음이 불편하면 진찰 후 추나 요법을 시행합니다. 엎드리지 않고 옆으로 눕거나 앉은 자세에서 부드럽게 풀며 세게 비트는 교정은 하지 않습니다. 굳은 허리에는 배에 닿지 않게 온열 요법을 더합니다.")+"\n"+H3("4. 한약")+"\n"+P("태를 편안히 하는 것을 바탕으로 허리 받침과 혈을 돕는 탕약을 처방하며, 임신 중 피할 약재는 쓰지 않습니다. 임신 중이거나 유산·조산 경험, 임신성 당뇨나 고혈압이 있다면 진료 때 꼭 알려 주세요. 확인 후 안전한 약재로 처방합니다.")),
("road","관리는 어떤 순서로 진행되나요?",ROAD([("안전 확인","주수와 산전 검사, 배 뭉침·출혈 여부를 먼저 확인합니다."),("통증 자리 구분","요통인지 골반띠·치골 통증인지 나누고 치료 자세를 정합니다."),("주 1~2회 치료","침과 약침, 부드러운 추나로 걷기와 잠자기를 편하게 만듭니다."),("출산 전후 연결","막달에는 횟수를 줄이고, 출산 뒤에는 산후 회복 관리로 이어 갑니다.")],note="횟수와 기간은 주수와 통증 정도에 따라 진찰 후 안내합니다.")),
("home","허리와 골반을 편하게 하는 생활 관리",UL([B("옆으로 누워 자기","왼쪽으로 누워 무릎 사이에 베개를 끼우면 골반이 벌어지지 않아 편합니다."),B("한 발 서기 줄이기","바지와 양말은 앉아서 입고, 차에서 내릴 때는 두 다리를 모아 함께 돌려 내립니다."),B("골반 받침 벨트","골반띠 통증에는 엉덩이뼈 높이를 감싸는 골반 벨트가 도움이 될 수 있습니다."),B("고양이 자세","네 발 자세에서 등을 천천히 말았다 펴기를 10번 하고, 배가 당기면 멈추세요."),B("낮은 신발과 짐 나누기","굽 낮은 신발을 신고, 무거운 짐은 가족에게 맡기세요.")])),
("other","다른 진료가 함께 필요한 경우",UL(["발끝까지 저리고 감각이 둔하면 디스크 여부를 확인해야 하며, 임신 중 영상 검사 여부는 병원에서 판단합니다.","열과 함께 옆구리가 아프면 산부인과나 내과에서 소변 검사를 받으세요.","임신성 당뇨, 고혈압, 갑상선 질환으로 처방받은 약은 담당 의사와 상의 없이 끊지 마세요.","통증으로 잠을 못 자고 우울감이 깊으면 산부인과에 알려 도움을 받으세요."])),
],
faq=[("배가 나온 상태에서 침 치료를 받아도 괜찮을까요?","주수를 확인하고 피할 혈을 빼고 얕게 놓습니다. 배 뭉침이나 출혈이 있으면 산부인과가 먼저입니다."),("임신 초기에도 치료할 수 있나요?","초기에는 자극을 더 줄이고 꼭 필요한 부위만 다룹니다. 진료 때 주수를 알려 주세요."),("파스나 진통제를 써도 되나요?","임신 중 피해야 할 성분이 있어 스스로 고르지 말고 산부인과에 확인하세요."),("골반띠 통증은 출산하면 사라지나요?","대개 출산 뒤 몇 달 안에 줄지만 남는 분도 있어 산후 관리가 필요합니다."),("엎드려야 하는 추나도 하나요?","하지 않습니다. 옆으로 눕거나 앉은 자세에서 부드럽게 시행합니다."),("임산부 요가나 걷기를 계속해도 되나요?","통증이 심해지지 않는 범위면 도움이 되고, 치골이 아프면 보폭을 줄이세요."),("임신 중 교통사고로 허리를 다쳤어요.","산부인과에서 태아 상태부터 확인하시고, 한방 진료는 자동차보험으로 가능합니다."),("집에서 남편이 눌러 줄 곳이 있나요?","옆으로 누운 채 무릎 뒤 위중혈이나 엉덩이 옆을 지그시 눌러 주세요. 천골 부위와 배는 누르지 마세요.")],
refs=[("Vleeming A, et al. European guidelines for the diagnosis and treatment of pelvic girdle pain. Eur Spine J, 2008",None),("Liddle SD, Pennick V. Interventions for preventing and treating low-back and pelvic pain during pregnancy. Cochrane Database Syst Rev, 2015",None),("허준, 『동의보감(東醫寶鑑)』 잡병편 부인(婦人)",None),KP]))
